import{_ as o,o as t,c as s,a0 as r}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"Functional Requirements — sharecli","description":"","frontmatter":{},"headers":[],"relativePath":"specs/FR.md","filePath":"specs/FR.md"}'),c={name:"specs/FR.md"};function d(i,e,n,a,l,p){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="functional-requirements-—-sharecli" tabindex="-1">Functional Requirements — sharecli <a class="header-anchor" href="#functional-requirements-—-sharecli" aria-label="Permalink to &quot;Functional Requirements — sharecli&quot;">​</a></h1><blockquote><p>Canonical FR index for the sharecli CLI. Each requirement is traceable to source code, tests, and acceptance criteria via <code>docs/specs/TRACEABILITY.md</code>.</p></blockquote><p><strong>Scope:</strong> This document defines the <em>minimum</em> set of Functional Requirements (FRs) that the sharecli binary MUST satisfy to be considered Phase 3 complete. Additional NFRs and design notes live in <code>SPEC.md</code> and <code>PRD.md</code>; this file is the spec-of-record for the CLI surface.</p><p><strong>Conventions:</strong></p><ul><li>FR IDs are stable: <code>FR-NNN</code>. They MUST NOT be renumbered once published.</li><li>Each FR has a single <strong>MUST</strong> statement, plus acceptance criteria (AC) that are independently testable.</li><li>The <code>Source</code> column points at the canonical Rust source file(s) that implement the requirement. The <code>Test</code> column points at the acceptance test file(s) that cover it.</li><li>Phase 3 only covers FR-001..FR-005. New FRs MAY be appended in later phases (FR-006, FR-007, …) but MUST NOT renumber or rewrite existing entries.</li></ul><hr><h2 id="fr-001-—-managed-process-lifecycle-start-list-stop" tabindex="-1">FR-001 — Managed Process Lifecycle (start / list / stop) <a class="header-anchor" href="#fr-001-—-managed-process-lifecycle-start-list-stop" aria-label="Permalink to &quot;FR-001 — Managed Process Lifecycle (start / list / stop)&quot;">​</a></h2><p><strong>Statement:</strong> The CLI MUST be able to start a named process associated with a project and harness type, list the running managed processes with optional filtering, and stop them by PID, project, harness, or <code>--all</code>.</p><p><strong>Source:</strong></p><ul><li><code>src/main.rs:38-91</code> — <code>Commands::Ps</code>, <code>Commands::Start</code>, <code>Commands::Stop</code> enum variants</li><li><code>src/commands/mod.rs:25-138</code> — <code>ps</code>, <code>start</code>, <code>stop</code> command implementations</li><li><code>src/runtime.rs:44-156</code> — <code>ProcessPool::spawn</code>, <code>ProcessPool::list</code>, <code>ProcessPool::kill</code>, <code>ProcessPool::kill_all</code></li></ul><p><strong>Acceptance Criteria:</strong></p><ul><li><strong>AC-001.1:</strong> <code>sharecli start &lt;project&gt; --harness &lt;harness&gt;</code> records a process in the in-memory <code>ProcessPool</code> and returns a non-zero PID.</li><li><strong>AC-001.2:</strong> <code>sharecli ps</code> prints a table with columns <code>PID</code>, <code>NAME</code>, <code>MEM(MB)</code>, <code>PROJECT</code>, <code>HARNESS</code> plus a totals footer.</li><li><strong>AC-001.3:</strong> <code>sharecli ps --project &lt;p&gt;</code> returns only processes whose <code>project</code> field equals <code>&lt;p&gt;</code>.</li><li><strong>AC-001.4:</strong> <code>sharecli stop --all</code> terminates every managed process and reports <code>All processes stopped.</code></li><li><strong>AC-001.5:</strong> <code>sharecli stop</code> with no selector exits with an error message instructing the user to specify <code>--pid</code>, <code>--project</code>, <code>--harness</code>, or <code>--all</code>.</li></ul><p><strong>Test refs:</strong> <code>tests/fr001_process_lifecycle.rs</code>, <code>tests/fr001_stop_filter.rs</code></p><hr><h2 id="fr-002-—-toml-configuration-management" tabindex="-1">FR-002 — TOML Configuration Management <a class="header-anchor" href="#fr-002-—-toml-configuration-management" aria-label="Permalink to &quot;FR-002 — TOML Configuration Management&quot;">​</a></h2><p><strong>Statement:</strong> The CLI MUST load, initialize, validate, and display its TOML configuration from the platform config directory (<code>$XDG_CONFIG_HOME/sharecli/config.toml</code> or OS equivalent), and it MUST persist project registrations across invocations.</p><p><strong>Source:</strong></p><ul><li><code>src/config.rs:1-119</code> — <code>Config</code>, <code>RuntimeConfig</code>, <code>Config::load</code>, <code>Config::init</code>, <code>Config::save</code></li><li><code>src/commands/mod.rs:194-222</code> — <code>config</code> command (Init, Validate, Show, Get, Set)</li></ul><p><strong>Acceptance Criteria:</strong></p><ul><li><strong>AC-002.1:</strong> <code>sharecli config init</code> creates the config directory if missing and writes a default TOML file that round-trips through <code>Config::load</code>.</li><li><strong>AC-002.2:</strong> <code>sharecli config validate</code> reports the number of registered projects on success.</li><li><strong>AC-002.3:</strong> <code>sharecli config show</code> prints the serialized TOML containing a <code>[projects]</code> and <code>[runtime]</code> table.</li><li><strong>AC-002.4:</strong> A <code>Config</code> deserialized from TOML preserves the <code>projects</code><code>HashMap&lt;String, String&gt;</code> and the <code>RuntimeConfig</code> fields (<code>node_path</code>, <code>bun_path</code>, <code>max_memory_mb</code>, <code>max_processes</code>).</li><li><strong>AC-002.5:</strong> <code>RuntimeConfig::default()</code> returns <code>max_memory_mb = Some(4096)</code> and <code>max_processes = Some(100)</code>.</li></ul><p><strong>Test refs:</strong> <code>tests/fr002_config_load.rs</code>, <code>tests/fr002_config_init.rs</code></p><hr><h2 id="fr-003-—-project-registry-add-list-show-discover-remove" tabindex="-1">FR-003 — Project Registry (add / list / show / discover / remove) <a class="header-anchor" href="#fr-003-—-project-registry-add-list-show-discover-remove" aria-label="Permalink to &quot;FR-003 — Project Registry (add / list / show / discover / remove)&quot;">​</a></h2><p><strong>Statement:</strong> The CLI MUST maintain a registry of named projects (each mapping to a filesystem path) under the <code>[projects]</code> table, and MUST support add, list, show, remove, and discover (recursive scan for git repos) operations.</p><p><strong>Source:</strong></p><ul><li><code>src/config.rs:8-68</code> — <code>Config.projects</code>, <code>default_projects</code></li><li><code>src/commands/mod.rs:225-313</code> — <code>project</code> command (Add, Remove, List, Show, Discover, Generate)</li></ul><p><strong>Acceptance Criteria:</strong></p><ul><li><strong>AC-003.1:</strong> <code>sharecli project add &lt;name&gt; &lt;path&gt;</code> inserts a new entry into <code>Config.projects</code> and persists the change via <code>Config::save</code>.</li><li><strong>AC-003.2:</strong> <code>sharecli project list</code> prints one <code>name -&gt; path</code> line per registered project, or the empty-state hint if none are registered.</li><li><strong>AC-003.3:</strong> <code>sharecli project show &lt;name&gt;</code> prints the resolved path and whether the path currently exists on disk.</li><li><strong>AC-003.4:</strong> <code>sharecli project discover [path]</code> scans the given directory and reports any subdirectory that contains a <code>.git</code> directory.</li><li><strong>AC-003.5:</strong> <code>sharecli project remove &lt;name&gt;</code> removes the entry from the <code>Config.projects</code> map and persists the change.</li></ul><p><strong>Test refs:</strong> <code>tests/fr003_project_registry.rs</code>, <code>tests/fr003_project_discover.rs</code></p><hr><h2 id="fr-004-—-process-pool-health-status" tabindex="-1">FR-004 — Process &amp; Pool Health Status <a class="header-anchor" href="#fr-004-—-process-pool-health-status" aria-label="Permalink to &quot;FR-004 — Process &amp; Pool Health Status&quot;">​</a></h2><p><strong>Statement:</strong> The CLI MUST be able to report the health of managed processes (per-harness counts, per-harness memory, system memory) and of the shared runtime pool (node/bun totals, idle count, in-use count, max-per-type), and MUST report per-process resource compliance.</p><p><strong>Source:</strong></p><ul><li><code>src/runtime.rs:152-356</code> — <code>system_memory_usage</code>, <code>SharedRuntime::status</code>, <code>SharedRuntime::health_check</code>, <code>PoolStatus</code>, <code>RuntimeHealth</code></li><li><code>src/monitoring.rs:1-118</code> — <code>HealthStatus</code>, <code>ProcessStats</code>, <code>MonitoringReport</code>, <code>ProcessStats::is_idle</code></li><li><code>src/commands/mod.rs:140-191</code> — <code>status</code> command</li><li><code>src/commands/mod.rs:325-396</code> — <code>pool_status</code>, <code>health</code> commands</li></ul><p><strong>Acceptance Criteria:</strong></p><ul><li><strong>AC-004.1:</strong> <code>sharecli status</code> prints a per-harness table of <code>(count, memory_mb)</code> totals, followed by a shared-runtime pool table, and a system-memory line.</li><li><strong>AC-004.2:</strong> <code>sharecli pool</code> reports node and bun pool totals, idle counts, and the <code>max_per_type</code> ceiling.</li><li><strong>AC-004.3:</strong> <code>sharecli health [--harness &lt;h&gt;]</code> reports <code>HEALTHY</code>/<code>DEGRADED</code> based on whether every pooled process is still alive and under the 1 GB high-memory threshold.</li><li><strong>AC-004.4:</strong> <code>HealthStatus::mark_unhealthy(reason)</code> increments <code>checks_failed</code> and emits a <code>Health check failed: &lt;reason&gt;</code> message to stderr.</li><li><strong>AC-004.5:</strong> <code>ProcessStats::is_idle(threshold)</code> returns <code>true</code> only when the process has been up longer than <code>threshold</code> seconds AND <code>cpu_percent &lt; 1.0</code>.</li></ul><p><strong>Test refs:</strong> <code>tests/fr004_status_health.rs</code>, <code>tests/fr004_pool_status.rs</code></p><hr><h2 id="fr-005-—-per-project-resource-limits" tabindex="-1">FR-005 — Per-Project Resource Limits <a class="header-anchor" href="#fr-005-—-per-project-resource-limits" aria-label="Permalink to &quot;FR-005 — Per-Project Resource Limits&quot;">​</a></h2><p><strong>Statement:</strong> The CLI MUST be able to set per-project memory and max-process-count limits, persist them in-memory across calls within a single process lifetime, and check whether the currently running processes for a project are within those limits.</p><p><strong>Source:</strong></p><ul><li><code>src/runtime.rs:358-455</code> — <code>ProjectLimits</code>, <code>ProjectResources::set_limits</code>, <code>ProjectResources::get_limits</code>, <code>ProjectResources::check_limits</code>, <code>ResourceCheck</code></li><li><code>src/commands/mod.rs:398-447</code> — <code>set_limits</code>, <code>check_limits</code> commands</li></ul><p><strong>Acceptance Criteria:</strong></p><ul><li><strong>AC-005.1:</strong> <code>ProjectLimits::default()</code> returns <code>memory_limit_mb = 1024</code>, <code>max_processes = 10</code>, <code>cpu_affinity = None</code>.</li><li><strong>AC-005.2:</strong> <code>sharecli limits &lt;project&gt; --memory &lt;mb&gt; --processes &lt;n&gt;</code> sets the project&#39;s limits and prints a confirmation.</li><li><strong>AC-005.3:</strong> <code>ProjectResources::get_limits</code> returns the most recently set limits, or <code>ProjectLimits::default()</code> for unknown projects.</li><li><strong>AC-005.4:</strong> <code>ResourceCheck::overall_ok</code> is <code>true</code> only when both <code>memory_ok</code> and <code>processes_ok</code> are <code>true</code>.</li><li><strong>AC-005.5:</strong> <code>sharecli check &lt;project&gt;</code> prints memory, process count, and per-axis status (<code>OK</code> / <code>EXCEEDED</code>) plus an overall verdict line.</li></ul><p><strong>Test refs:</strong> <code>tests/fr005_project_limits.rs</code>, <code>tests/fr005_resource_check.rs</code></p><hr><h2 id="fr-012-—-serve-http-federated-authn" tabindex="-1">FR-012 — Serve HTTP Federated AuthN <a class="header-anchor" href="#fr-012-—-serve-http-federated-authn" aria-label="Permalink to &quot;FR-012 — Serve HTTP Federated AuthN&quot;">​</a></h2><p><strong>Statement:</strong> When <code>sharecli serve</code> is configured with <code>auth_mode = &quot;jwt&quot;</code> (or an equivalent <code>[serve.jwt]</code> block), non-probe HTTP routes MUST reject requests whose <code>Authorization: Bearer</code> JWT fails signature or <code>iss</code> / <code>aud</code> / <code>exp</code> validation against the configured JWKS. <code>/healthz</code> and <code>/readyz</code> MUST remain public.</p><p><strong>Source:</strong></p><ul><li><code>src/serve_auth.rs</code> — JWT / JWKS validation middleware</li><li><code>src/config.rs</code> — <code>ServeConfig</code> / <code>ServeJwtConfig</code></li><li><code>src/commands/serve.rs</code> — AuthN wiring at serve startup</li><li><code>docs/ops/AUTH.md</code> — operator guide</li></ul><p><strong>Acceptance Criteria:</strong></p><ul><li><strong>AC-012.1:</strong> Valid RS256 JWT with matching <code>iss</code>/<code>aud</code> is authorized (returns <code>sub</code> from claims).</li><li><strong>AC-012.2:</strong> Expired JWT is rejected with reason <code>jwt_expired</code>.</li><li><strong>AC-012.3:</strong> Wrong <code>aud</code> / <code>iss</code> are rejected; probe paths stay public (see unit tests for <code>/healthz</code> <code>/readyz</code>).</li></ul><p><strong>Test refs:</strong> <code>tests/fr012_serve_jwt_auth.rs</code>, <code>src/serve_auth.rs</code> unit tests</p><hr><h2 id="nfr-notes-out-of-scope-for-fr-001-fr-005-fr-012" tabindex="-1">NFR Notes (out of scope for FR-001..FR-005 / FR-012) <a class="header-anchor" href="#nfr-notes-out-of-scope-for-fr-001-fr-005-fr-012" aria-label="Permalink to &quot;NFR Notes (out of scope for FR-001..FR-005 / FR-012)&quot;">​</a></h2><ul><li><strong>NFR-001 Platform Support:</strong> The CLI MUST build and run on Linux, macOS, and Windows. Process-pool tests are gated with <code>#[cfg(unix)]</code> / <code>#[cfg(windows)]</code> blocks to honour this.</li><li><strong>NFR-002 Observability:</strong> The CLI MUST emit structured logs via <code>tracing</code>/<code>tracing-subscriber</code>, gated on <code>--verbose</code> / <code>--quiet</code>.</li><li><strong>NFR-003 Error Handling:</strong> All commands MUST return <code>anyhow::Result&lt;()&gt;</code> and MUST NOT panic on missing config (FR-002 covers the missing-file case by returning <code>Config::default()</code>).</li></ul><p>These NFRs are documented for context only; acceptance tests for them will land in a later phase (FR-006+).</p>',57)])])}const g=o(c,[["render",d]]);export{m as __pageData,g as default};
